package trackerweb

const workersTemplate = `{{define "workers"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workers · SavewebHQ</title><link rel="stylesheet" href="/assets/admin.css"></head><body><header><a class="brand" href="{{if .Admin}}/admin{{else}}/worker{{end}}">SavewebHQ</a></header><main><div class="breadcrumbs"><a href="{{if .Admin}}/admin{{else}}/worker{{end}}">{{if .Admin}}Projects{{else}}Worker{{end}}</a><span>/</span><span>Workers</span></div><div class="page-title"><div><h1>{{if .Admin}}Workers{{else}}My workers{{end}}</h1><p>{{if .WorkerID}}Exact match for <code>{{.WorkerID}}</code>{{else if .UserID}}Workers for <code>{{.UserID}}</code>{{else}}200 most recently used mappings{{end}}</p></div>{{if .Admin}}<div><form method="get" action="/admin/workers" class="inline-form"><label>Worker ID<input name="worker_id" value="{{.WorkerID}}" maxlength="128" pattern="[A-Za-z0-9._:-]+" required></label><button type="submit">Find worker</button></form><form method="get" action="/admin/workers" class="inline-form"><label>User ID<input name="user_id" value="{{.UserID}}" maxlength="128" pattern="[A-Za-z0-9._:-]+" required></label><button type="submit">Find user workers</button>{{if or .WorkerID .UserID}}<a class="button" href="/admin/workers">Clear</a>{{end}}</form></div>{{end}}</div><section class="table-wrap"><table><thead><tr><th>Worker ID</th><th>User ID</th><th>Last seen</th></tr></thead><tbody>{{range .Workers}}<tr class="{{if eq .WorkerID $.WorkerID}}selected-row{{end}}"><td><code>{{.WorkerID}}</code></td><td>{{if $.Admin}}<a href="/admin/users?user_id={{.UserID}}#user-form"><code>{{.UserID}}</code></a>{{else}}<code>{{.UserID}}</code>{{end}}</td><td>{{.LastSeenAt}}</td></tr>{{else}}<tr><td colspan="3" class="empty">No worker mapping found</td></tr>{{end}}</tbody></table></section></main></body></html>{{end}}`
